{
  "findings": [
    {
      "check_id": "CKV_GCP_13",
      "title": "Client certificate authentication enabled",
      "resource": "google_container_cluster.k8sexample",
      "severity": "HIGH",
      "explanation": "The cluster explicitly enables client certificate authentication (`issue_client_certificate = true`). This is deprecated and less secure than using IAM or service accounts for access control."
    },
    {
      "check_id": "CKV_GCP_7",
      "title": "Legacy ABAC authorization enabled",
      "resource": "google_container_cluster.k8sexample",
      "severity": "MEDIUM",
      "explanation": "The cluster has `enable_legacy_abac = \"true\"`. Legacy Attribute-Based Access Control (ABAC) is deprecated and should be disabled in favor of RBAC."
    },
    {
      "check_id": "CKV2_GCP_19",
      "title": "Alpha cluster features enabled",
      "resource": "google_container_cluster.k8sexample",
      "severity": "MEDIUM",
      "explanation": "The cluster has `enable_kubernetes_alpha = \"true\"`. Alpha features are unstable, unsupported, and may introduce security vulnerabilities or breaking changes."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Static credentials in master_auth block",
      "resource": "google_container_cluster.k8sexample",
      "severity": "CRITICAL",
      "explanation": "The `master_auth` block uses static username and password variables. Static credentials are a significant security risk; modern GKE clusters should rely on IAM integration and disable basic auth entirely."
    }
  ],
  "patched_code": "resource \"google_container_cluster\" \"k8sexample\" {\n  name               = \"${var.vault_user}-k8s-cluster\"\n  description        = \"example k8s cluster\"\n  zone               = \"${var.gcp_zone}\"\n  initial_node_count = \"${var.initial_node_count}\"\n  enable_kubernetes_alpha = \"false\"\n  enable_legacy_abac = \"false\"\n  \n  # Disable basic authentication and client certificates\n  master_auth {\n    username = \"\"\n    password = \"\"\n    client_certificate_config {\n      issue_client_certificate = false\n    }\n  }\n\n  node_config {\n    machine_type = \"${var.node_machine_type}\"\n    disk_size_gb = \"${var.node_disk_size}\"\n    oauth_scopes = [\n      \"https://www.googleapis.com/auth/compute\",\n      \"https://www.googleapis.com/auth/devstorage.read_only\",\n      \"https://www.googleapis.com/auth/logging.write\",\n      \"https://www.googleapis.com/auth/monitoring\"\n    ]\n  }\n}",
  "fix_summary": "Disabled Kubernetes alpha features and legacy ABAC authorization. Removed static credentials from the master_auth block by setting username/password to empty strings and disabling client certificate issuance, enforcing reliance on IAM-based authentication."
}
